void showMsg(BuildContext context, String msg, {bool error = false}) {
  ScaffoldMessenger.of(context)
    ..hideCurrentSnackBar()
    ..showSnackBar(SnackBar(
      content: Text(msg),
      backgroundColor: error ? Naya.danger : Naya.greenDark,
      behavior: SnackBarBehavior.floating,
    ));
}

/// Endesha kazi, onyesha kosa kama ipo. Inarudisha true ikifanikiwa.
Future<bool> runTask(BuildContext context, Future<void> Function() task, {String? success}) async {
  try {
    await task();
    if (success != null && context.mounted) showMsg(context, success);
    return true;
  } catch (e) {
    if (context.mounted) showMsg(context, errorText(e), error: true);
    return false;
  }
}

/// Inaweka koma kwenye kiasi wakati wa kuandika: 1250000 -> 1,250,000
class ThousandsFormatter extends TextInputFormatter {
  final _f = NumberFormat('#,##0', 'en_US');
  @override
  TextEditingValue formatEditUpdate(TextEditingValue oldValue, TextEditingValue newValue) {
    final digits = newValue.text.replaceAll(RegExp(r'[^0-9]'), '');
    if (digits.isEmpty) return const TextEditingValue(text: '');
    final text = _f.format(int.parse(digits));
    return TextEditingValue(text: text, selection: TextSelection.collapsed(offset: text.length));
  }
}

class MoneyField extends StatelessWidget {
  final TextEditingController controller;
  final String label;
  final bool autofocus;
  final bool required;
  final bool allowNegative;
  const MoneyField({
    super.key,
    required this.controller,
    required this.label,
    this.autofocus = false,
    this.required = true,
    this.allowNegative = false,
  });

  @override
  Widget build(BuildContext context) {
    return TextFormField(
      controller: controller,
      autofocus: autofocus,
      keyboardType: TextInputType.number,
      inputFormatters: [ThousandsFormatter()],
      style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w600),
      decoration: InputDecoration(labelText: label, prefixText: 'TSh ', border: const OutlineInputBorder()),
      validator: (v) {
        if (!required) return null;
        if (v == null || v.trim().isEmpty) return 'Weka kiasi';
        return null;
      },
    );
  }
}

class StatCard extends StatelessWidget {
  final String title;
  final String value;
  final IconData icon;
  final Color? color;
  final String? subtitle;
  const StatCard({super.key, required this.title, required this.value, required this.icon, this.color, this.subtitle});

  @override
  Widget build(BuildContext context) {
    final c = color ?? Naya.green;
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(14),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisAlignment: MainAxisAlignment.center, children: [
          Row(children: [
            Container(
              padding: const EdgeInsets.all(6),
              decoration: BoxDecoration(color: c.withValues(alpha: 0.12), borderRadius: BorderRadius.circular(10)),
              child: Icon(icon, size: 16, color: c),
            ),
            const SizedBox(width: 8),
            Expanded(
              child: Text(title,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(color: Naya.muted, fontWeight: FontWeight.w700, fontSize: 12)),
            ),
          ]),
          const SizedBox(height: 8),
          FittedBox(
            fit: BoxFit.scaleDown,
            alignment: Alignment.centerLeft,
            child: Text(value, style: display(20)),
          ),
          if (subtitle != null) Text(subtitle!, style: const TextStyle(fontSize: 11, color: Naya.muted)),
        ]),
      ),
    );
  }
}

/// Alama ya WakalaLink: kisanduku cha kijani chenye "W" ya dhahabu
class BrandMark extends StatelessWidget {
  final double size;
  final bool onDark;
  final bool showName;
  const BrandMark({super.key, this.size = 40, this.onDark = false, this.showName = true});

  @override
  Widget build(BuildContext context) {
    final mark = Container(
      width: size,
      height: size,
      alignment: Alignment.center,
      decoration: BoxDecoration(
        color: onDark ? Colors.white.withValues(alpha: 0.12) : Naya.green,
        borderRadius: BorderRadius.circular(size * 0.3),
        border: onDark ? Border.all(color: Colors.white.withValues(alpha: 0.18)) : null,
      ),
      child: Text('W', style: display(size * 0.58, color: Naya.gold)),
    );
    if (!showName) return mark;
    return Row(mainAxisSize: MainAxisSize.min, children: [
      mark,
      SizedBox(width: size * 0.28),
      Text(AppConfig.appName, style: display(size * 0.6, color: onDark ? Colors.white : Naya.ink)),
    ]);
  }
}

/// Kadi kubwa ya kijani kizito (salio la sasa, muhtasari wa leo)
class HeroPanel extends StatelessWidget {
  final Widget child;
