  const HeroPanel({super.key, required this.child, this.padding = const EdgeInsets.all(18)});

  @override
  Widget build(BuildContext context) {
    return Container(
      margin: const EdgeInsets.symmetric(vertical: 5),
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(22),
        gradient: const LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [Naya.greenDark, Naya.greenDeep],
        ),
        boxShadow: [
          BoxShadow(color: Naya.greenDeep.withValues(alpha: 0.25), blurRadius: 24, offset: const Offset(0, 10)),
        ],
      ),
      child: Stack(children: [
        // pambo dogo la dhahabu pembeni
        Positioned(
          right: -30,
          top: -30,
          child: Container(
            width: 120,
            height: 120,
            decoration: BoxDecoration(shape: BoxShape.circle, color: Naya.gold.withValues(alpha: 0.10)),
          ),
        ),
        Padding(padding: padding, child: child),
      ]),
    );
  }
}

